package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.math.util.MathUtils.factorial
 */
public class MathUtils_factorial_TriageGen2Test {

    @Test
    public void testFactorialValidRange() {
        // Testing boundary and regular values within [1, 20]
        // Note: The implementation throws IllegalArgumentException if n < 1.
        // Based on the code: if (n < 1) throw IllegalArgumentException.
        // This implies n=1 is the smallest valid input according to the logic provided.

        assertEquals(1L, MathUtils.factorial(1));
        assertEquals(2L, MathUtils.factorial(2));
        assertEquals(6L, MathUtils.factorial(3));
        assertEquals(120L, MathUtils.factorial(5));
        assertEquals(3628800L, MathUtils.factorial(10));
        assertEquals(2432902008176640000L, MathUtils.factorial(20));
    }








}

